# ==============================================================================
# 03_decontaminate_and_aggregate.R
# SOILWARM — primary community preprocessing, 2022-2024
# ==============================================================================
# AIM
# ---
# Produce the PRIMARY community tables used by the article from the raw marker
# objects generated by script 02.
#
# ORDER OF OPERATIONS
# -------------------
# 1. contaminant detection at sequence-feature level using all available
#    negative controls (3 extraction blanks + technical blanks when present);
# 2. remove contaminant sequence features;
# 3. retain features assigned to the focal rank;
# 4. SUM features belonging to the same family/genus;
# 5. calculate prevalence on aggregated taxa;
# 6. retain taxa occurring in >= PRIMARY_PREVALENCE of biological samples.
#
# PRIMARY RANKS
# -------------
# Archaea = Family
# Bacteria = Family
# Fungi = Genus
# Nematodes = Genus
# Protists = Genus
#
# The metadata and configuration must agree on the same primary 3-year scope.
# ==============================================================================

source("R/config.R")

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(purrr)
  library(tibble)
  library(ggplot2)
  library(stringr)
  library(readxl)
})

source("R/functions_soilwarm.R")

require_intermediate(
  file.path(INT_DIR, "01_sample_map.rds"),
  "scripts/01_build_sample_map.R"
)
require_intermediate(
  file.path(INT_DIR, "01b_metadata_final.rds"),
  "scripts/01b_build_metadata_final.R"
)
require_intermediate(
  file.path(INT_DIR, "02_raw_markers_broad.rds"),
  "scripts/02_import_raw_markers.R"
)

sample_map <- readRDS(file.path(INT_DIR, "01_sample_map.rds"))
metadata_final <- readRDS(file.path(INT_DIR, "01b_metadata_final.rds"))
raw_markers_broad <- readRDS(file.path(INT_DIR, "02_raw_markers_broad.rds"))

analysis_years <- sort(unique(as.integer(metadata_final$Year)))

if (!identical(analysis_years, sort(PRIMARY_YEARS))) {
  stop(
    "Primary community preprocessing years disagree with PRIMARY_YEARS. Found: ",
    paste(analysis_years, collapse = ", "),
    "; configured: ",
    paste(PRIMARY_YEARS, collapse = ", "),
    ".",
    call. = FALSE
  )
}

if (nrow(metadata_final) != EXPECTED_PRIMARY_N) {
  stop(
    "Expected ", EXPECTED_PRIMARY_N,
    " metadata rows; found ", nrow(metadata_final), ".",
    call. = FALSE
  )
}

if (!setequal(metadata_final$MET, sample_map$biological$MET)) {
  stop(
    "metadata_final and the canonical sample map do not contain the same 108 MET IDs.",
    call. = FALSE
  )
}

# Use the central configuration so the primary ranks cannot silently drift
# between preprocessing and later sensitivity analyses.
primary_ranks <- PRIMARY_RANKS

missing_markers <- setdiff(names(primary_ranks), names(raw_markers_broad))
if (length(missing_markers) > 0L) {
  stop(
    "Missing raw marker objects: ",
    paste(missing_markers, collapse = ", "),
    call. = FALSE
  )
}

prep <- purrr::imap(
  raw_markers_broad,
  function(obj, marker) {
    prepare_marker_table(
      obj = obj,
      rank = primary_ranks[[marker]],
      analysis_years = analysis_years,
      prevalence = PRIMARY_PREVALENCE,
      contaminant_method = "decontam",
      decontam_threshold = PRIMARY_DECONTAM_THRESHOLD
    )
  }
)

# All five prepared tables must contain the same 108 biological libraries.
prepared_ids <- lapply(prep, function(x) rownames(x$counts))

if (!all(vapply(prepared_ids, length, integer(1)) == EXPECTED_PRIMARY_N)) {
  stop(
    "At least one prepared marker table does not contain ",
    EXPECTED_PRIMARY_N,
    " biological samples.",
    call. = FALSE
  )
}

ref_ids <- prepared_ids[[1]]
same_sets <- vapply(
  prepared_ids,
  function(x) setequal(x, ref_ids),
  logical(1)
)

if (!all(same_sets)) {
  stop(
    "Prepared marker tables do not contain the same biological MET IDs: ",
    paste(names(same_sets)[!same_sets], collapse = ", "),
    call. = FALSE
  )
}

saveRDS(
  prep,
  file.path(INT_DIR, "03_primary_prepared_tables.rds")
)

for (marker in names(prep)) {
  saveRDS(
    prep[[marker]]$counts,
    file.path(INT_DIR, paste0("03_count_", tolower(marker), ".rds"))
  )

  write.csv(
    cbind(
      sample_id = rownames(prep[[marker]]$counts),
      as.data.frame(prep[[marker]]$counts)
    ),
    file.path(TABLE_DIR, paste0("03_abundance_", tolower(marker), ".csv")),
    row.names = FALSE
  )
}

summary_tab <- dplyr::bind_rows(purrr::map(prep, "summary"))
sample_qc <- dplyr::bind_rows(purrr::map(prep, "sample_qc"))
taxon_qc <- dplyr::bind_rows(purrr::map(prep, "taxon_qc"))
contam_qc <- purrr::imap_dfr(
  prep,
  ~ dplyr::mutate(.x$contamination, marker = .y)
)

write.csv(
  summary_tab,
  file.path(TABLE_DIR, "03_preprocessing_summary.csv"),
  row.names = FALSE
)
write.csv(
  sample_qc,
  file.path(TABLE_DIR, "03_sample_assignment_QC.csv"),
  row.names = FALSE
)
write.csv(
  taxon_qc,
  file.path(TABLE_DIR, "03_taxon_prevalence_QC.csv"),
  row.names = FALSE
)
write.csv(
  contam_qc,
  file.path(TABLE_DIR, "03_decontam_diagnostics.csv"),
  row.names = FALSE
)

p <- sample_qc |>
  ggplot(aes(x = marker, y = assigned_fraction)) +
  geom_hline(yintercept = c(0.5, 0.75), linetype = 3, linewidth = 0.3) +
  geom_boxplot(outlier.shape = NA) +
  geom_jitter(width = 0.15, alpha = 0.45, size = 1.3) +
  coord_cartesian(ylim = c(0, 1)) +
  labs(
    x = NULL,
    y = "Fraction of post-decontamination reads assigned at focal rank"
  ) +
  theme_bw() +
  theme(axis.text.x = element_text(angle = 35, hjust = 1))

ggsave(
  file.path(FIG_DIR, "03_taxonomic_assignment_fraction.pdf"),
  p,
  width = 8,
  height = 5
)

message("Primary taxon tables saved for 2022-2024 (108 biological samples).")
message("Inspect results/tables/03_preprocessing_summary.csv before proceeding.")
message("Next script: scripts/04_primary_MCOA.R")
